            Java

    import java.util.LinkedList;
import java.util.Queue;

class Process {}

class Semaphore {
    int value;
    Queue<Process> q = new LinkedList<>();

    void P() {
        value--;
        if (value < 0) {
            // add process to queue
            // here p is a process which is currently executing
            q.add(p);
            block();
        }
    }

    void V() {
        value++;
        if (value <= 0) {
            // remove process p from queue
            Process p = q.poll();
            wakeup(p);
        }
    }

    void block() {}
    void wakeup(Process p) {}
}


